class Solution:

	def countTriplets(self, arr):
		cnt = 0
		n = len(arr)
		li = [{1: 1, 2: 0, 3: 0} for i in range(n)]
		for i in range(1, n):
			for j in range(i):
				if arr[i] > arr[j]:
					li[i][2] += li[j][1]
					li[i][3] += li[j][2]
			cnt = cnt + li[i][3]
		return cnt
